-- Additive page-media upgrade. Review and apply explicitly; no runtime DDL.
CREATE TABLE IF NOT EXISTS blog_landing (
 id BIGINT UNSIGNED NOT NULL PRIMARY KEY, title VARCHAR(250) NOT NULL DEFAULT 'Sri Lanka Travel Blog', slug VARCHAR(280) NOT NULL DEFAULT '', intro LONGTEXT NULL, cta_title VARCHAR(255) NULL, cta_text LONGTEXT NULL, meta_title VARCHAR(255) NULL, meta_description VARCHAR(320) NULL, canonical_url VARCHAR(255) NULL, is_published TINYINT(1) NOT NULL DEFAULT 1, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT IGNORE INTO blog_landing(id,title,intro) VALUES(1,'Sri Lanka Travel Blog','Tips, guides, and stories from the island.');
CREATE TABLE IF NOT EXISTS page_gallery_images (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, content_type VARCHAR(32) NOT NULL, content_id BIGINT UNSIGNED NOT NULL, media_asset_id BIGINT UNSIGNED NOT NULL, alt_text VARCHAR(255) NOT NULL, sort_order INT NOT NULL DEFAULT 0, KEY idx_page_gallery(content_type,content_id,sort_order,id), KEY idx_page_gallery_asset(media_asset_id), CONSTRAINT fk_page_gallery_asset FOREIGN KEY(media_asset_id) REFERENCES media_assets(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
